        async _scWaitShopRefreshAck(ackBefore, tag) {
            const verifyMs = Math.max(1000, Math.min(60000, Number(sgsT('shopVerifyMs', 30000)) || 30000));
            const timeoutMs = Math.max(1000, Math.min(verifyMs,
                sgsFast() ? (Number(sgsT('shopVerifyCapMs', 30000)) || verifyMs) : verifyMs));
            const pollMs = Math.max(10, Math.min(500, Number(sgsT('shopPollMs', 25)) || 25));
            const t0 = Date.now();
            const before = Number(ackBefore) || 0;
            while (Date.now() - t0 < timeoutMs) {
                const seq = this._scShopRefreshAckSeq();
                if (seq > before) {
                    const errCode = window.__sgsRespErr
                        ? window.__sgsRespErr['cmsg.CRespShopRefreshChess']
                        : null;
                    return {
                        acknowledged: true,
                        accepted: errCode == null || Number(errCode) === 0,
                        errCode: errCode,
                        ms: Date.now() - t0,
                    };
                }
                const remaining = timeoutMs - (Date.now() - t0);
                await this._sleepJs(Math.min(pollMs, Math.max(1, remaining)), false, true);
            }
            return { acknowledged: false, accepted: false, ms: Date.now() - t0, tag: tag };
        },

        async _scWaitShopRefreshGap() {
            const lastRefreshAt = this._scLastShopRefreshAt || 0;
            if (!lastRefreshAt) return false;
            const remaining = sgsT('shopRefreshGapMs', 100) - (Date.now() - lastRefreshAt);
            if (remaining > 0) {
                await this._sleepJs(remaining, false, true);
                return true;
            }
            return false;
        },

