                //   这一轮压根不会先试"不带目标", 无目标类锦囊(无中生有/五谷丰登)就会被指向牌库那张卡。
                const specs = [{ fixed: { id: 0, label: '直接使用(不指定目标)' } }];
                for (let _i = 1; _i <= 6; _i++) specs.push({ step: { on: String(_i) } });    // 牌库第 _i 格
                for (let _i = 1; _i <= 7; _i++) specs.push({ step: { on: 'field' + _i } }); // 阵上第 _i 格
