            const reqTyp = parseInt(opt.reqMinionTyp, 10) || 0;
            let typList = null;
            try { typList = mgr.ChessMinionTypList; } catch (_) { }
            if (Array.isArray(typList)) out.before.minionTypList = typList.slice(0, 16);
            if (reqTyp && Array.isArray(typList) && typList.length && typList.indexOf(reqTyp) < 0) {
                out.reason = '这个主公要求兵种类型 ' + reqTyp + ', 但本局可用兵种只有 ['
                    + typList.join(',') + '] —— 游戏的 CheckGeneralAlive 会拦掉, 包根本不会发。换一个主公。';
                return out;
            }
            let friendUID = 0;
            try { friendUID = parseInt(mgr.FriendUID, 10) || 0; } catch (_) { }
            out.before.friendUID = friendUID;
            if (gid === 1001 && friendUID) {
                out.reason = '组队局(FriendUID=' + friendUID + ')不能选董卓(1001) —— '
                    + 'CheckGeneralAlive 里有 "!this.FriendUID || 1001 != e" 这条硬编码。';
                return out;
            }
