                    try { w = (typeof wm.GetInstanceWindow === 'function') ? wm.GetInstanceWindow(N) : null; } catch (_) { }
                    if (!w) { try { w = (typeof wm.GetWindow === 'function') ? wm.GetWindow(N) : null; } catch (_) { } }
                    if (w) { this._sgDiag = 'WindowManager.' + N + ' 命中'; return w; }
                    // v4.152★ 按【resName】扫 —— 类里写死 this.resName="tavernChessSelectGeneral",
                    //   比类名更稳(类名可能被打包改掉, 资源名不会)。遍历 WindowManager 上
                    //   所有看起来像窗口表的字段, 找 resName 匹配且可见的那个。
                    const RN = 'tavernChessSelectGeneral';
