                        try { s = parseInt(mgr.selfGeneralID, 10) || 0; } catch (_) { }
                        try { pr = parseInt(mgr.selfPreGeneralID, 10) || 0; } catch (_) { }
                        try { tid2 = parseInt(mgr.TableID, 10) || 0; } catch (_) { }
                        try { endTx = parseInt(mgr.endChooseGeneralStageTime, 10) || 0; } catch (_) { }
